use vstd::prelude::*;

verus! {

fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
    ensures
        // The outer vector has exactly one element
        result.len() == 1,
        // The inner vector has the same length as the input array
        result[0].len() == arr.len(),
        // All elements are preserved in order
        forall|i: int| 0 <= i && i < arr.len() ==> result[0][i] == arr[i],
{
    // Create a new outer vector with exactly one element
    let mut result_vec = Vec::new();
    
    // Create a copy of the input array to use as the inner vector
    let mut inner_vec = Vec::new();
    
    // Copy all elements from arr to inner_vec
    let mut index: usize = 0;
    while index < arr.len()
        invariant
            0 <= index <= arr.len(),
            inner_vec.len() == index,
            forall|j: int| 0 <= j && j < index ==> inner_vec[j] == arr[j],
    {
        inner_vec.push(arr[index]);
        index = index + 1;
    }
    
    // Add the inner vector to the result
    result_vec.push(inner_vec);
    
    result_vec
}

} // verus!